import React, { useState, useEffect, useRef } from 'react';
import './SearchWidget.css';

const SearchWidget = ({ isVisible = false, searchResults = '', onClose }) => {
    const [position, setPosition] = useState({ top: '12vh', left: '6vh' });
    const [isDragging, setIsDragging] = useState(false);
    const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
    const widgetRef = useRef(null);

    // Handle widget dragging
    const handleMouseDown = (e) => {
        if (e.target.classList.contains('widget-controls') || e.target.closest('.widget-controls')) {
            return;
        }

        setIsDragging(true);
        setDragStart({
            x: e.clientX - widgetRef.current.getBoundingClientRect().left,
            y: e.clientY - widgetRef.current.getBoundingClientRect().top
        });

        // Add dragging class for visual feedback
        widgetRef.current.classList.add('widget-dragging');
    };

    const handleMouseMove = (e) => {
        if (!isDragging) return;

        const newLeft = e.clientX - dragStart.x;
        const newTop = e.clientY - dragStart.y;

        setPosition({
            top: `${newTop}px`,
            left: `${newLeft}px`
        });
    };

    const handleMouseUp = () => {
        if (isDragging) {
            setIsDragging(false);
            widgetRef.current.classList.remove('widget-dragging');
        }
    };

    // Add event listeners for dragging
    useEffect(() => {
        if (isDragging) {
            document.addEventListener('mousemove', handleMouseMove);
            document.addEventListener('mouseup', handleMouseUp);
        } else {
            document.removeEventListener('mousemove', handleMouseMove);
            document.removeEventListener('mouseup', handleMouseUp);
        }

        return () => {
            document.removeEventListener('mousemove', handleMouseMove);
            document.removeEventListener('mouseup', handleMouseUp);
        };
    }, [isDragging]);

    // Handle widget controls
    const handleClose = () => {
        if (onClose) onClose();
    };

    const handleExpand = () => {
        // Expand widget functionality
        const currentWidth = widgetRef.current.offsetWidth;
        const currentHeight = widgetRef.current.offsetHeight;

        widgetRef.current.style.width = `${currentWidth * 1.2}px`;
        widgetRef.current.style.height = `${currentHeight * 1.2}px`;
    };

    const handleCompress = () => {
        // Compress widget functionality
        const currentWidth = widgetRef.current.offsetWidth;
        const currentHeight = widgetRef.current.offsetHeight;

        widgetRef.current.style.width = `${currentWidth * 0.8}px`;
        widgetRef.current.style.height = `${currentHeight * 0.8}px`;
    };

    // Handle keyboard navigation for scrolling
    const handleKeyDown = (e) => {
        const searchContent = widgetRef.current.querySelector('.search-content');
        if (!searchContent) return;

        const scrollAmount = 30;

        switch (e.key) {
            case 'ArrowUp':
                e.preventDefault();
                searchContent.scrollTop -= scrollAmount;
                break;
            case 'ArrowDown':
                e.preventDefault();
                searchContent.scrollTop += scrollAmount;
                break;
            case 'PageUp':
                e.preventDefault();
                searchContent.scrollTop -= searchContent.clientHeight * 0.8;
                break;
            case 'PageDown':
                e.preventDefault();
                searchContent.scrollTop += searchContent.clientHeight * 0.8;
                break;
            case 'Home':
                e.preventDefault();
                searchContent.scrollTop = 0;
                break;
            case 'End':
                e.preventDefault();
                searchContent.scrollTop = searchContent.scrollHeight;
                break;
            default:
                break;
        }
    };

    // Format search results for display
    const formatSearchResults = (results) => {
        if (!results) return '';

        // Convert newlines to HTML line breaks
        return results.replace(/\n/g, '<br/>');
    };

    if (!isVisible) return null;

    return (
        <div
            ref={widgetRef}
            className="search-widget"
            style={{
                top: position.top,
                left: position.left,
                display: isVisible ? 'block' : 'none'
            }}
            onMouseDown={handleMouseDown}
            onKeyDown={handleKeyDown}
            tabIndex="0"
        >
            {/* Corner brackets */}
            <div className="corner-top-right"></div>
            <div className="corner-bottom-left"></div>

            {/* Widget controls */}
            <div className="widget-controls">
                <button
                    className="widget-control-btn"
                    title="Make Bigger"
                    onClick={handleExpand}
                >
                    +
                </button>
                <button
                    className="widget-control-btn"
                    title="Make Smaller"
                    onClick={handleCompress}
                >
                    -
                </button>
                <button
                    className="widget-control-btn"
                    title="Close"
                    onClick={handleClose}
                >
                    ×
                </button>
            </div>

            {/* Search label */}
            <div className="search-label">SEARCH RESULTS</div>

            {/* Search content */}
            <div
                className="search-content"
                dangerouslySetInnerHTML={{ __html: formatSearchResults(searchResults) }}
            />

            {/* Resize handle */}
            <div className="resize-handle"></div>
        </div>
    );
};

export default SearchWidget;
